-- Batch 003: upload and SHA-256 verify every image before applying.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":765,"word":"aspire","meaning":"嚮往","example":"Mina aspires to become an astronomer and studies the stars every night.","example_zh":"米娜立志成為天文學家，每晚都研究星星。","original_meaning":"嚮往","original_example":"She aspires to be a scientist.","original_example_zh":"她立志成為一名科學家。"},{"source_id":766,"word":"assert","meaning":"斷言","example":"Leo asserted that the bridge was safe and pointed to his successful test.","example_zh":"里歐斷言這座橋很安全，並指著他成功完成的測試。","original_meaning":"斷言","original_example":"He asserted his innocence.","original_example_zh":"他聲稱自己無罪。"},{"source_id":767,"word":"asset","meaning":"資產","example":"Our school's greenhouse is a valuable asset for science classes.","example_zh":"學校的溫室是自然科學課程的一項寶貴資產。","original_meaning":"資產","original_example":"Education is a valuable asset.","original_example_zh":"教育是一項寶貴的資產。"},{"source_id":768,"word":"authorize","meaning":"授權","example":"The teacher will authorize our group to use the school telescope.","example_zh":"老師將授權我們這組使用學校的望遠鏡。","original_meaning":"授權","original_example":"He authorized the payment.","original_example_zh":"他批准了這筆付款。"},{"source_id":772,"word":"betray","meaning":"背叛","example":"Tom betrayed his teammates by giving their game plan to the other team.","example_zh":"湯姆把比賽計畫交給對手，背叛了隊友。","original_meaning":"背叛","original_example":"He betrayed his friends.","original_example_zh":"他背叛了朋友。"},{"source_id":773,"word":"bias","meaning":"偏見","example":"The judge showed bias by favoring his own team's weaker model.","example_zh":"評審偏袒自己隊伍較差的模型，顯露出偏見。","original_meaning":"偏見","original_example":"Avoid personal bias.","original_example_zh":"避免個人偏見。"},{"source_id":775,"word":"blunt","meaning":"鈍的；直率的","example":"The blunt scissors could not cut the thick paper.","example_zh":"這把鈍剪刀剪不開厚紙。","original_meaning":"鈍的；直率的","original_example":"A blunt response.","original_example_zh":"一句直率的回應。"},{"source_id":777,"word":"breach","meaning":"違反","example":"Entering the fenced area was a breach of the safety rules.","example_zh":"進入圍起來的區域違反了安全規定。","original_meaning":"違反","original_example":"A breach of contract.","original_example_zh":"違約。"},{"source_id":779,"word":"brutal","meaning":"殘暴的；猛烈的","example":"The brutal storm destroyed the small wooden shelter.","example_zh":"這場猛烈的暴風雨摧毀了小木棚。","original_meaning":"殘暴的","original_example":"A brutal attack.","original_example_zh":"一次殘暴的攻擊。"},{"source_id":780,"word":"bulk","meaning":"大量","example":"The club buys paper in bulk to save money.","example_zh":"社團大量購買紙張來省錢。","original_meaning":"大量","original_example":"I understood the bulk of what you were saying, just one of two points I need to hear again.","original_example_zh":"我大致上都聽懂了，只是有兩點需要再聽一次。"},{"source_id":782,"word":"cease","meaning":"停止","example":"The students waited for the rain to cease before leaving the library.","example_zh":"學生等雨停了，才離開圖書館。","original_meaning":"停止","original_example":"The rain ceased.","original_example_zh":"雨停了。"},{"source_id":784,"word":"civic","meaning":"公民的","example":"The students showed civic responsibility by cleaning the public park.","example_zh":"學生清理公園，展現公民責任。","original_meaning":"公民的","original_example":"Volunteering is a great way to show your civic duty to your community.","original_example_zh":"志願服務是向社區展現公民責任的絕佳方式。"},{"source_id":786,"word":"coincide","meaning":"同時發生；巧合","example":"Our birthdays coincide, so we decided to have one party.","example_zh":"我們的生日恰巧同一天，所以決定一起辦派對。","original_meaning":"巧合","original_example":"Our opinions coincide.","original_example_zh":"我們的意見一致。"},{"source_id":788,"word":"compel","meaning":"迫使","example":"The heavy rain compelled us to move the picnic indoors.","example_zh":"大雨迫使我們把野餐移到室內。","original_meaning":"迫使","original_example":"She was compelled to resign.","original_example_zh":"她被迫辭職。"},{"source_id":789,"word":"complement","meaning":"補充；相輔相成","example":"The fresh salad complements the warm pasta perfectly.","example_zh":"新鮮沙拉和熱騰騰的義大利麵搭配得恰到好處。","original_meaning":"補充","original_example":"The two colors complement each other.","original_example_zh":"這兩種顏色相得益彰。"},{"source_id":790,"word":"comply","meaning":"遵守","example":"We comply with the lab rules by wearing safety goggles.","example_zh":"我們戴上護目鏡，遵守實驗室規定。","original_meaning":"遵守","original_example":"Comply with the regulations.","original_example_zh":"遵守法規。"},{"source_id":792,"word":"compound","meaning":"化合物","example":"Water is a compound made from hydrogen and oxygen.","example_zh":"水是由氫和氧組成的化合物。","original_meaning":"化合物","original_example":"A chemical compound.","original_example_zh":"一種化學化合物。"},{"source_id":793,"word":"conceive","meaning":"構想","example":"Ella conceived a plan to turn old bottles into plant pots.","example_zh":"艾拉構想出把舊瓶子變成花盆的計畫。","original_meaning":"構想","original_example":"She conceived a brilliant plan.","original_example_zh":"她構思出一個絕妙的計劃。"},{"source_id":794,"word":"condemn","meaning":"譴責","example":"The class condemned the act of throwing rubbish into the river.","example_zh":"全班譴責把垃圾丟進河裡的行為。","original_meaning":"譴責","original_example":"The world condemned the attack.","original_example_zh":"國際社會譴責這起攻擊。"},{"source_id":795,"word":"confine","meaning":"限制","example":"Please confine the paint to the area inside the frame.","example_zh":"請把油漆限制在框內的區域。","original_meaning":"限制","original_example":"Confine the discussion to the topic.","original_example_zh":"請將討論限於主題範圍內。"},{"source_id":796,"word":"conform","meaning":"遵從","example":"The players must conform to the same uniform rules.","example_zh":"球員必須遵從相同的制服規定。","original_meaning":"遵從","original_example":"Conform to social norms.","original_example_zh":"遵守社會規範。"},{"source_id":799,"word":"consensus","meaning":"共識","example":"The group reached a consensus to build a birdhouse.","example_zh":"小組達成共識，決定製作鳥屋。","original_meaning":"共識","original_example":"We reached a consensus.","original_example_zh":"我們達成了共識。"},{"source_id":800,"word":"consent","meaning":"同意","example":"The student asked for her friend's consent before taking a photo.","example_zh":"這位學生拍照前，先徵求朋友的同意。","original_meaning":"同意","original_example":"With your consent.","original_example_zh":"經你同意。"},{"source_id":802,"word":"constraint","meaning":"限制","example":"The small budget was a constraint on our robot project.","example_zh":"有限的預算限制了我們的機器人計畫。","original_meaning":"限制","original_example":"Budget constraints.","original_example_zh":"預算限制。"},{"source_id":803,"word":"contemplate","meaning":"沉思","example":"Nora sat by the lake to contemplate her future.","example_zh":"諾拉坐在湖邊，思考自己的未來。","original_meaning":"沉思","original_example":"She contemplated her future.","original_example_zh":"她思索著自己的未來。"},{"source_id":804,"word":"contempt","meaning":"輕蔑","example":"The player showed contempt by sneering at the beginner's effort.","example_zh":"這名球員嘲笑初學者的努力，顯露輕蔑。","original_meaning":"輕蔑","original_example":"He showed contempt.","original_example_zh":"他表現出蔑視。"},{"source_id":805,"word":"contend","meaning":"爭奪；聲稱","example":"Two school teams will contend for the debate trophy.","example_zh":"兩支校隊將爭奪辯論賽獎盃。","original_meaning":"爭奪；聲稱","original_example":"They contend for the title.","original_example_zh":"他們爭奪冠軍頭銜。"},{"source_id":806,"word":"contradict","meaning":"矛盾","example":"The wet ground seemed to contradict his claim that it had not rained.","example_zh":"濕漉漉的地面似乎和他聲稱沒下雨的說法矛盾。","original_meaning":"矛盾","original_example":"Your actions contradict your words.","original_example_zh":"你的言行不一。"},{"source_id":810,"word":"corporate","meaning":"企業的","example":"The students visited a corporate office to learn about business.","example_zh":"學生參訪企業辦公室，了解商業運作。","original_meaning":"企業的","original_example":"Corporate culture.","original_example_zh":"企業文化。"},{"source_id":811,"word":"corresponding","meaning":"對應的","example":"Match each key with its corresponding lock.","example_zh":"把每把鑰匙和它對應的鎖配對。","original_meaning":"對應的","original_example":"The corresponding number.","original_example_zh":"對應的號碼。"},{"source_id":812,"word":"corrupt","meaning":"腐敗的","example":"The corrupt official secretly accepted money to approve the plan.","example_zh":"這名貪腐官員私下收錢，以批准這項計畫。","original_meaning":"腐敗的","original_example":"A corrupt government.","original_example_zh":"一個腐敗的政府。"},{"source_id":813,"word":"courtesy","meaning":"禮貌","example":"Holding the door for someone is a simple act of courtesy.","example_zh":"替別人扶著門是一個簡單的禮貌舉動。","original_meaning":"禮貌","original_example":"Show some courtesy.","original_example_zh":"展現禮貌。"},{"source_id":814,"word":"craft","meaning":"工藝","example":"She learned the traditional craft of weaving baskets.","example_zh":"她學會了編織籃子這項傳統工藝。","original_meaning":"工藝","original_example":"Traditional crafts.","original_example_zh":"傳統工藝。"},{"source_id":815,"word":"credible","meaning":"可信的","example":"The students chose a credible source with clear scientific evidence.","example_zh":"學生選擇有明確科學證據的可信來源。","original_meaning":"可信的","original_example":"A credible source.","original_example_zh":"一個可信的來源。"},{"source_id":816,"word":"curriculum","meaning":"課程；課程規劃","example":"Our new curriculum includes robotics and gardening classes.","example_zh":"我們的新課程規劃包含機器人與園藝課。","original_meaning":"課程；課程規劃","original_example":"Our new curriculum includes a class on personal finance and online safety.","original_example_zh":"學校的新課程加入了個人理財與網路安全課。"},{"source_id":818,"word":"deem","meaning":"認為","example":"The coach deemed the broken helmet unsafe to use.","example_zh":"教練認為這頂破裂的安全帽不宜使用。","original_meaning":"認為","original_example":"It was deemed necessary.","original_example_zh":"這被認為是必要的。"},{"source_id":819,"word":"deficit","meaning":"赤字","example":"The club had a deficit because its costs exceeded ticket sales.","example_zh":"社團的成本超過售票收入，因此出現赤字。","original_meaning":"赤字","original_example":"A budget deficit.","original_example_zh":"預算赤字。"},{"source_id":821,"word":"delegate","meaning":"委派","example":"The team leader will delegate the painting to two classmates.","example_zh":"隊長將把上色工作委派給兩位同學。","original_meaning":"委派","original_example":"Delegate tasks to your team.","original_example_zh":"將任務委派給你的團隊。"},{"source_id":822,"word":"depict","meaning":"描繪","example":"Her painting will depict the old bridge beside our school.","example_zh":"她的畫將描繪學校旁的老橋。","original_meaning":"描繪","original_example":"The painting depicts a garden.","original_example_zh":"這幅畫描繪了一個花園。"},{"source_id":824,"word":"deprive","meaning":"剝奪","example":"The new wall would deprive the garden of sunlight.","example_zh":"新圍牆會使花園失去陽光。","original_meaning":"剝奪","original_example":"Deprive someone of freedom.","original_example_zh":"剝奪某人的自由。"},{"source_id":825,"word":"derive","meaning":"源自","example":"The village derives its electricity from the river.","example_zh":"這座村莊的電力來自河流。","original_meaning":"源自","original_example":"The word derives from Latin.","original_example_zh":"這個詞源自拉丁文。"},{"source_id":826,"word":"designate","meaning":"指定","example":"The teacher will designate this table as the first-aid station.","example_zh":"老師將指定這張桌子作為急救站。","original_meaning":"指定","original_example":"She was designated as leader.","original_example_zh":"她被指定為領導人。"},{"source_id":827,"word":"despair","meaning":"絕望","example":"He felt despair when he saw his ruined science project.","example_zh":"他看到毀掉的科展作品時感到絕望。","original_meaning":"絕望","original_example":"A feeling of despair.","original_example_zh":"絕望的感覺。"},{"source_id":830,"word":"diagnose","meaning":"診斷","example":"The doctor used an X-ray to diagnose the broken arm.","example_zh":"醫師利用 X 光診斷出手臂骨折。","original_meaning":"診斷","original_example":"The doctor diagnosed the illness.","original_example_zh":"醫生診斷出該疾病。"},{"source_id":832,"word":"diplomatic","meaning":"外交的","example":"The countries reached a diplomatic agreement to share the river.","example_zh":"這些國家透過外交協商，同意共享河流。","original_meaning":"外交的","original_example":"A diplomatic solution.","original_example_zh":"一個外交上的解決方案。"},{"source_id":833,"word":"discard","meaning":"丟棄","example":"Please discard the torn cardboard in the recycling bin.","example_zh":"請把破掉的紙板丟進回收桶。","original_meaning":"丟棄","original_example":"Discard the old files.","original_example_zh":"刪除舊檔案。"},{"source_id":834,"word":"disclose","meaning":"揭露","example":"The scientist will disclose the discovery at the school talk.","example_zh":"這位科學家將在校園講座中公開這項發現。","original_meaning":"揭露","original_example":"He disclosed the secret.","original_example_zh":"他洩露了秘密。"},{"source_id":836,"word":"displace","meaning":"取代","example":"The new machine will displace the old hand pump.","example_zh":"這台新機器將取代舊的手壓幫浦。","original_meaning":"取代","original_example":"Machines displace workers.","original_example_zh":"機器取代工人。"},{"source_id":837,"word":"dispose","meaning":"處置","example":"We dispose of used batteries at a special collection point.","example_zh":"我們把用過的電池送到專門的回收點處理。","original_meaning":"處置","original_example":"Dispose of waste properly.","original_example_zh":"妥善處理廢棄物。"},{"source_id":838,"word":"dispute","meaning":"爭端","example":"A dispute arose over which team could use the court first.","example_zh":"兩隊為了誰能先使用球場而發生爭執。","original_meaning":"爭端","original_example":"A labor dispute.","original_example_zh":"勞資糾紛。"},{"source_id":839,"word":"disrupt","meaning":"擾亂","example":"A fallen tree disrupted the school bus route.","example_zh":"一棵倒下的樹擾亂了校車行程。","original_meaning":"擾亂","original_example":"The storm disrupted traffic.","original_example_zh":"風暴導致交通中斷。"},{"source_id":840,"word":"dissolve","meaning":"溶解","example":"Stir the sugar until it begins to dissolve in the warm water.","example_zh":"攪拌砂糖，直到它開始溶解在溫水中。","original_meaning":"溶解","original_example":"Salt dissolves in water.","original_example_zh":"鹽會溶於水。"},{"source_id":842,"word":"distort","meaning":"扭曲","example":"The curved mirror can distort your reflection.","example_zh":"曲面鏡會使你的倒影變形。","original_meaning":"扭曲","original_example":"Do not distort the facts.","original_example_zh":"請勿歪曲事實。"},{"source_id":845,"word":"domain","meaning":"領域","example":"Marine biology is the scientist's main domain of research.","example_zh":"海洋生物學是這位科學家的主要研究領域。","original_meaning":"領域","original_example":"The public domain.","original_example_zh":"公共領域。"},{"source_id":848,"word":"drain","meaning":"排水","example":"The students helped drain the water from the flooded playground.","example_zh":"學生幫忙排掉操場上的積水。","original_meaning":"排水","original_example":"Drain the pool.","original_example_zh":"將泳池放空。"},{"source_id":849,"word":"drought","meaning":"乾旱","example":"The long drought left the farm's soil dry and cracked.","example_zh":"長期乾旱使農田土壤乾裂。","original_meaning":"乾旱","original_example":"A severe drought.","original_example_zh":"嚴重的乾旱。"},{"source_id":850,"word":"durable","meaning":"耐用的","example":"These durable boots survived years of muddy hiking trips.","example_zh":"這雙耐用的靴子經過多年泥濘健行，仍然完好。","original_meaning":"耐用的","original_example":"A durable material.","original_example_zh":"一種耐用的材料。"},{"source_id":851,"word":"dynamic","meaning":"動態的；充滿活力的","example":"The dynamic teacher filled the classroom with energy.","example_zh":"這位充滿活力的老師讓教室充滿朝氣。","original_meaning":"動態的","original_example":"A dynamic environment.","original_example_zh":"一個充滿活力的環境。"},{"source_id":852,"word":"ecosystem","meaning":"生態系統","example":"The pond's ecosystem includes fish, frogs, plants, and insects.","example_zh":"池塘的生態系統包含魚、青蛙、植物和昆蟲。","original_meaning":"生態系統","original_example":"Removing trash from the stream helps the entire ecosystem, not just the fish.","original_example_zh":"清除溪流垃圾能幫助整個生態系，不只是魚類。"},{"source_id":854,"word":"emission","meaning":"排放；排放物","example":"The factory reduced its smoke emission by installing a filter.","example_zh":"工廠裝設過濾器，減少了煙霧排放。","original_meaning":"排放；排放物","original_example":"The report compares carbon emissions from buses and private cars.","original_example_zh":"這份報告比較公車與自用車的碳排放量。"},{"source_id":855,"word":"empathy","meaning":"同理心","example":"Lily showed empathy by listening to her upset friend.","example_zh":"莉莉專心聆聽難過的朋友，展現同理心。","original_meaning":"同理心","original_example":"Show empathy towards others.","original_example_zh":"對他人展現同理心。"},{"source_id":857,"word":"endeavor","meaning":"努力；費力的工作","example":"Restoring the neglected garden was a challenging endeavor.","example_zh":"修復荒廢花園是一項充滿挑戰的工作。","original_meaning":"努力","original_example":"A worthy endeavor.","original_example_zh":"一項值得投入的事業。"},{"source_id":858,"word":"endorse","meaning":"支持","example":"The coach agreed to endorse the students' charity run.","example_zh":"教練同意支持學生舉辦的公益路跑。","original_meaning":"支持","original_example":"She endorsed the product.","original_example_zh":"她為該產品背書。"},{"source_id":859,"word":"enforce","meaning":"執行","example":"The lifeguard will enforce the rule against running near the pool.","example_zh":"救生員會執行泳池邊禁止奔跑的規定。","original_meaning":"執行","original_example":"Enforce the law.","original_example_zh":"執行法律。"},{"source_id":861,"word":"enterprise","meaning":"企業","example":"The students started a small enterprise selling handmade soap.","example_zh":"學生創辦了一家販售手工皂的小企業。","original_meaning":"企業","original_example":"A private enterprise.","original_example_zh":"一家私營企業。"},{"source_id":863,"word":"entrepreneur","meaning":"企業家；創業家","example":"The young entrepreneur opened a bicycle repair shop.","example_zh":"這位年輕創業家開了一間腳踏車維修店。","original_meaning":"企業家","original_example":"A successful entrepreneur.","original_example_zh":"一位成功的企業家。"},{"source_id":867,"word":"escalate","meaning":"升級","example":"The argument began to escalate until the teacher stepped in.","example_zh":"爭論逐漸升高，直到老師介入。","original_meaning":"升級","original_example":"The conflict escalated.","original_example_zh":"衝突升級了。"},{"source_id":868,"word":"essence","meaning":"本質；核心","example":"Cooperation is the essence of this team-building activity.","example_zh":"合作是這項團隊活動的核心。","original_meaning":"本質","original_example":"The essence of the problem.","original_example_zh":"問題的本質。"},{"source_id":869,"word":"eternal","meaning":"永恆的","example":"The ancient story describes an eternal flame that never goes out.","example_zh":"這個古老故事描述了一團永不熄滅的火焰。","original_meaning":"永恆的","original_example":"some eternal villain","original_example_zh":"某個永恆的反派"},{"source_id":871,"word":"excel","meaning":"擅長","example":"Rina excels at playing the violin and leads the school orchestra.","example_zh":"莉娜擅長拉小提琴，並擔任學校管弦樂團首席。","original_meaning":"擅長","original_example":"She excels in math.","original_example_zh":"她在數學方面表現優異。"},{"source_id":874,"word":"expenditure","meaning":"支出","example":"The club recorded every expenditure on tools and wood.","example_zh":"社團記錄了每一筆工具與木材支出。","original_meaning":"支出","original_example":"Government expenditure.","original_example_zh":"政府支出。"},{"source_id":875,"word":"explicit","meaning":"明確的","example":"The instructor gave explicit directions for folding the paper crane.","example_zh":"老師清楚說明紙鶴的摺法。","original_meaning":"明確的","original_example":"Give explicit instructions.","original_example_zh":"給予明確的指示。"},{"source_id":877,"word":"extinction","meaning":"滅絕","example":"The museum explains how the dodo was driven to extinction.","example_zh":"這座博物館說明渡渡鳥如何走向滅絕。","original_meaning":"滅絕","original_example":"Scientists collect genetic samples to protect rare plants from extinction.","original_example_zh":"科學家蒐集基因樣本，保護稀有植物免於滅絕。"},{"source_id":878,"word":"extract","meaning":"提取","example":"We used a press to extract juice from the oranges.","example_zh":"我們用榨汁器從柳橙中榨出果汁。","original_meaning":"提取","original_example":"Extract the data.","original_example_zh":"提取資料。"},{"source_id":881,"word":"fatal","meaning":"致命的","example":"Eating this poisonous mushroom can be fatal.","example_zh":"吃下這種毒蘑菇可能致命。","original_meaning":"致命的","original_example":"A fatal accident.","original_example_zh":"一場致命的事故。"},{"source_id":882,"word":"feasible","meaning":"可行的","example":"A small rooftop garden is feasible with these lightweight boxes.","example_zh":"使用這些輕型箱子，就能在屋頂設置小花園。","original_meaning":"可行的","original_example":"A feasible plan.","original_example_zh":"一個可行的計畫。"},{"source_id":883,"word":"flaw","meaning":"缺陷","example":"A small flaw in the wooden wheel made the model wobble.","example_zh":"木輪上的一個小缺陷使模型搖晃。","original_meaning":"缺陷","original_example":"That vase has a flaw.","original_example_zh":"那個花瓶有瑕疵。"},{"source_id":884,"word":"flourish","meaning":"繁榮","example":"The plants began to flourish after we improved the soil.","example_zh":"我們改善土壤後，植物開始茁壯生長。","original_meaning":"繁榮","original_example":"The business flourished.","original_example_zh":"生意興隆。"},{"source_id":887,"word":"foremost","meaning":"最重要的","example":"Keeping everyone safe is our foremost concern on the trip.","example_zh":"讓每個人平安是這趟旅程最重要的考量。","original_meaning":"最重要的","original_example":"The foremost expert.","original_example_zh":"首屈一指的專家。"},{"source_id":890,"word":"foster","meaning":"促進；寄養","example":"The group project helped foster friendship among the students.","example_zh":"這項小組計畫幫助學生培養友誼。","original_meaning":"促進；寄養","original_example":"Foster creativity.","original_example_zh":"培養創造力。"},{"source_id":891,"word":"fraction","meaning":"小部分","example":"Only a small fraction of the cake was left after the party.","example_zh":"派對過後，蛋糕只剩一小部分。","original_meaning":"小部分","original_example":"Only a fraction of the cost.","original_example_zh":"僅需一小部分的費用。"},{"source_id":892,"word":"fragment","meaning":"碎片","example":"She found a fragment of a broken pot in the garden.","example_zh":"她在花園找到一片破陶盆的碎片。","original_meaning":"碎片","original_example":"A fragment of glass.","original_example_zh":"一塊玻璃碎片。"},{"source_id":893,"word":"framework","meaning":"架構","example":"The students built a wooden framework for the greenhouse.","example_zh":"學生為溫室搭建木製骨架。","original_meaning":"架構","original_example":"A legal framework.","original_example_zh":"一個法律框架。"},{"source_id":895,"word":"friction","meaning":"摩擦","example":"Friction between the tires and the road helps the bicycle stop.","example_zh":"輪胎與路面的摩擦力有助於腳踏車停下來。","original_meaning":"摩擦","original_example":"Reduce friction.","original_example_zh":"減少摩擦。"},{"source_id":899,"word":"glimpse","meaning":"一瞥","example":"I caught a glimpse of a deer between the trees.","example_zh":"我從樹木間瞥見一隻鹿。","original_meaning":"一瞥","original_example":"A glimpse of the future.","original_example_zh":"一瞥未來。"},{"source_id":901,"word":"grace","meaning":"優雅","example":"The dancer moved with grace across the stage.","example_zh":"舞者優雅地移動，穿過舞台。","original_meaning":"優雅","original_example":"She dances with grace.","original_example_zh":"她舞姿優雅。"},{"source_id":902,"word":"grasp","meaning":"抓住；理解","example":"The climber reached up to grasp the next handhold.","example_zh":"攀岩者伸手抓住下一個攀岩點。","original_meaning":"抓住；理解","original_example":"Grasp the concept.","original_example_zh":"掌握這個概念。"},{"source_id":903,"word":"grave","meaning":"嚴重的","example":"The damaged bridge posed a grave danger to travelers.","example_zh":"受損的橋梁對旅客構成嚴重危險。","original_meaning":"嚴重的","original_example":"A grave mistake.","original_example_zh":"嚴重的錯誤。"},{"source_id":904,"word":"grieve","meaning":"悲傷","example":"The family gathered to grieve the loss of their old dog.","example_zh":"家人聚在一起，哀悼老狗離世。","original_meaning":"悲傷","original_example":"She grieved for her loss.","original_example_zh":"她為失去而悲傷。"},{"source_id":905,"word":"gross","meaning":"總的；嚴重的","example":"The stall's gross income includes all sales before costs.","example_zh":"攤位的總收入包含扣除成本前的全部銷售所得。","original_meaning":"總的；嚴重的","original_example":"Gross domestic product.","original_example_zh":"國內生產總值。"},{"source_id":907,"word":"habitat","meaning":"棲息地","example":"The wetland is an important habitat for many birds.","example_zh":"這片濕地是許多鳥類的重要棲息地。","original_meaning":"棲息地","original_example":"Protect natural habitats.","original_example_zh":"保護自然棲息地。"},{"source_id":908,"word":"halt","meaning":"停止","example":"The crossing guard raised her hand to halt the traffic.","example_zh":"導護人員舉起手，讓車輛停下來。","original_meaning":"停止","original_example":"Halt the production.","original_example_zh":"停止生產。"},{"source_id":909,"word":"handicap","meaning":"障礙","example":"A lack of tools was a serious handicap for our building project.","example_zh":"工具不足是我們建造計畫的一大障礙。","original_meaning":"障礙","original_example":"Overcome a handicap.","original_example_zh":"克服障礙。"},{"source_id":910,"word":"harass","meaning":"騷擾","example":"The teacher stepped in when students began to harass a classmate.","example_zh":"有學生開始騷擾同學時，老師立即介入。","original_meaning":"騷擾","original_example":"He was harassed at work.","original_example_zh":"他在工作中受到騷擾。"},{"source_id":911,"word":"harmony","meaning":"和諧","example":"The singers practiced until their voices blended in harmony.","example_zh":"歌手反覆練習，直到聲音和諧融合。","original_meaning":"和諧","original_example":"Live in harmony.","original_example_zh":"和睦共處。"},{"source_id":912,"word":"harvest","meaning":"收穫","example":"The students helped harvest ripe tomatoes from the school garden.","example_zh":"學生幫忙採收校園菜園裡成熟的番茄。","original_meaning":"收穫","original_example":"The autumn harvest.","original_example_zh":"秋收。"},{"source_id":913,"word":"hazard","meaning":"危險","example":"The loose cable was a tripping hazard in the hallway.","example_zh":"走廊上鬆散的電線有讓人絆倒的危險。","original_meaning":"危險","original_example":"A health hazard.","original_example_zh":"健康危害。"},{"source_id":914,"word":"hinder","meaning":"阻礙","example":"The fallen branches hinder our progress along the trail.","example_zh":"倒下的樹枝阻礙我們沿步道前進。","original_meaning":"阻礙","original_example":"Rain hindered our progress.","original_example_zh":"雨水阻礙了我們的行程。"},{"source_id":915,"word":"horizontal","meaning":"水平的","example":"Draw a horizontal line across the middle of the paper.","example_zh":"在紙張中央畫一條水平線。","original_meaning":"水平的","original_example":"A horizontal line.","original_example_zh":"一條水平線。"},{"source_id":916,"word":"hostile","meaning":"敵意的","example":"The stray cat became hostile when the dog came too close.","example_zh":"狗靠得太近時，那隻流浪貓變得充滿敵意。","original_meaning":"敵意的","original_example":"A hostile environment.","original_example_zh":"一個充滿敵意的環境。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Batch 003 source rows changed; refusing to overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-aspire-01-v1","level":"senior","word":"aspire","sort_order":1,"sense":"嚮往","alt_zh":"高中女生在陽台用望遠鏡觀星，桌上放著行星模型。","example":"Mina aspires to become an astronomer and studies the stars every night.","example_zh":"米娜立志成為天文學家，每晚都研究星星。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/aspire-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-assert-01-v1","level":"senior","word":"assert","sort_order":1,"sense":"斷言","alt_zh":"高中生自信地指著承受多個砝碼仍穩固的模型橋。","example":"Leo asserted that the bridge was safe and pointed to his successful test.","example_zh":"里歐斷言這座橋很安全，並指著他成功完成的測試。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/assert-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-asset-01-v1","level":"senior","word":"asset","sort_order":1,"sense":"資產","alt_zh":"老師帶高中生在學校溫室觀察茂盛的植物。","example":"Our school's greenhouse is a valuable asset for science classes.","example_zh":"學校的溫室是自然科學課程的一項寶貴資產。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/asset-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-authorize-01-v1","level":"senior","word":"authorize","sort_order":1,"sense":"授權","alt_zh":"老師把觀測室鑰匙交給高中生，後方可見大型望遠鏡。","example":"The teacher will authorize our group to use the school telescope.","example_zh":"老師將授權我們這組使用學校的望遠鏡。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/authorize-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-betray-01-v1","level":"senior","word":"betray","sort_order":1,"sense":"背叛","alt_zh":"穿藍色球衣的高中生偷偷把戰術圖交給紅隊，藍隊隊友驚訝地看見。","example":"Tom betrayed his teammates by giving their game plan to the other team.","example_zh":"湯姆把比賽計畫交給對手，背叛了隊友。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/betray-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-bias-01-v1","level":"senior","word":"bias","sort_order":1,"sense":"偏見","alt_zh":"戴藍色隊徽的評審選擇搖晃的藍隊模型，忽略穩固的紅隊模型。","example":"The judge showed bias by favoring his own team's weaker model.","example_zh":"評審偏袒自己隊伍較差的模型，顯露出偏見。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/bias-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-blunt-01-v1","level":"senior","word":"blunt","sort_order":1,"sense":"鈍的；直率的","alt_zh":"高中生用鈍剪刀剪厚卡紙，紙張只有折痕而沒有被剪開。","example":"The blunt scissors could not cut the thick paper.","example_zh":"這把鈍剪刀剪不開厚紙。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/blunt-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-breach-01-v1","level":"senior","word":"breach","sort_order":1,"sense":"違反","alt_zh":"高中生跨進施工圍欄，工作人員立刻用手勢制止。","example":"Entering the fenced area was a breach of the safety rules.","example_zh":"進入圍起來的區域違反了安全規定。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/breach-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-brutal-01-v1","level":"senior","word":"brutal","sort_order":1,"sense":"殘暴的；猛烈的","alt_zh":"暴風雨吹斷樹枝並掀開木棚屋頂，學生從安全的窗內望去。","example":"The brutal storm destroyed the small wooden shelter.","example_zh":"這場猛烈的暴風雨摧毀了小木棚。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/brutal-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-bulk-01-v1","level":"senior","word":"bulk","sort_order":1,"sense":"大量","alt_zh":"高中生合力把多箱成批購買的紙搬進社團教室。","example":"The club buys paper in bulk to save money.","example_zh":"社團大量購買紙張來省錢。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/bulk-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-cease-01-v1","level":"senior","word":"cease","sort_order":1,"sense":"停止","alt_zh":"雨雲散去後，學生在圖書館門口收起雨傘，地面仍有水窪。","example":"The students waited for the rain to cease before leaving the library.","example_zh":"學生等雨停了，才離開圖書館。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/cease-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-civic-01-v1","level":"senior","word":"civic","sort_order":1,"sense":"公民的","alt_zh":"高中生戴手套在公園撿拾垃圾，旁邊有其他居民一起參與。","example":"The students showed civic responsibility by cleaning the public park.","example_zh":"學生清理公園，展現公民責任。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/civic-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-coincide-01-v1","level":"senior","word":"coincide","sort_order":1,"sense":"同時發生；巧合","alt_zh":"兩位高中生驚喜地站在同一張桌旁，各有一個生日蛋糕。","example":"Our birthdays coincide, so we decided to have one party.","example_zh":"我們的生日恰巧同一天，所以決定一起辦派對。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/coincide-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-compel-01-v1","level":"senior","word":"compel","sort_order":1,"sense":"迫使","alt_zh":"突降大雨，學生抱著野餐籃急忙進入室內。","example":"The heavy rain compelled us to move the picnic indoors.","example_zh":"大雨迫使我們把野餐移到室內。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/se